import Head from "next/head";
import { SITE_URL, absoluteUrl } from "../../lib/blog/site-config";

type JsonLd = Record<string, unknown>;

type SeoHeadProps = {
  title: string;
  description: string;
  /** Canonical URL. Relative paths are made absolute against SITE_URL. */
  canonical: string;
  /** OG/Twitter image. Defaults to the home card, generated by `npm run seo:assets`. */
  image?: string;
  imageAlt?: string;
  /** Width/height of `image`; social crawlers use them to reserve the card slot. */
  imageWidth?: number;
  imageHeight?: number;
  /** "website" for landing pages, "article" for blog posts. */
  ogType?: "website" | "article";
  /** Set to false on utility pages and on filtered/sorted duplicates. */
  index?: boolean;
  /** Structured data blocks rendered as separate <script type="application/ld+json">. */
  jsonLd?: JsonLd[];
};

/** 1200x630 is the card size Open Graph and Twitter are tuned for. */
export const DEFAULT_OG_IMAGE = "/images/og-setproduct-home.jpg";
const DEFAULT_OG_WIDTH = 1200;
const DEFAULT_OG_HEIGHT = 630;

// A page that may appear under many URLs (search results, filters) is a
// duplicate; `max-image-preview:large` asks Google for a big thumbnail in
// results instead of the small square, which lifts click-through.
const ROBOTS_INDEX = "index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1";
const ROBOTS_NOINDEX = "noindex, follow";

/**
 * Single source of truth for page metadata.
 *
 * Before this component every page repeated eleven <meta> lines by hand, and
 * they had already drifted: some pages shipped og:title without og:image,
 * some used `property` for twitter tags (crawlers look for `name`), and none
 * declared `og:site_name` or the image size. Anything that is true for the
 * whole site lives here; a page passes only what it knows about itself.
 */
export default function SeoHead({
  title,
  description,
  canonical,
  image = DEFAULT_OG_IMAGE,
  imageAlt,
  imageWidth = DEFAULT_OG_WIDTH,
  imageHeight = DEFAULT_OG_HEIGHT,
  ogType = "website",
  index = true,
  jsonLd = [],
}: SeoHeadProps) {
  const pageUrl = canonical.startsWith("http") ? canonical : absoluteUrl(canonical);
  const imageUrl = absoluteUrl(image);
  const resolvedImageAlt = imageAlt ?? title;

  return (
    <Head>
      <title>{title}</title>
      <meta name="description" content={description} />
      <link rel="canonical" href={pageUrl} />
      <meta name="robots" content={index ? ROBOTS_INDEX : ROBOTS_NOINDEX} />

      <meta property="og:type" content={ogType} />
      <meta property="og:site_name" content="Setproduct" />
      <meta property="og:locale" content="en_US" />
      <meta property="og:title" content={title} />
      <meta property="og:description" content={description} />
      <meta property="og:url" content={pageUrl} />
      <meta property="og:image" content={imageUrl} />
      <meta property="og:image:alt" content={resolvedImageAlt} />
      <meta property="og:image:width" content={String(imageWidth)} />
      <meta property="og:image:height" content={String(imageHeight)} />
      <meta property="og:image:type" content={imageUrl.endsWith(".jpg") ? "image/jpeg" : "image/png"} />

      {/* Twitter reads `name`, not `property`. */}
      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:site" content="@set_product" />
      <meta name="twitter:title" content={title} />
      <meta name="twitter:description" content={description} />
      <meta name="twitter:image" content={imageUrl} />
      <meta name="twitter:image:alt" content={resolvedImageAlt} />

      {jsonLd.map((block, i) => (
        <script
          dangerouslySetInnerHTML={{ __html: JSON.stringify(block) }}
          key={i}
          type="application/ld+json"
        />
      ))}
    </Head>
  );
}

/** Canonical URL for a path that is not the site root. */
export function pageUrl(pathname: string): string {
  return `${SITE_URL}${pathname.startsWith("/") ? pathname : `/${pathname}`}`;
}
